"use client";

import Link from "next/link";

import {
  DollarSign,
  TrendingUp,
  Package,
  AlertTriangle,
  ShoppingCart,
  ArrowUpRight,
  ArrowDownRight,
  Pill,
  Clock,
  CheckCircle2,
  Loader2
} from "lucide-react";
import { useData } from "@/lib/hooks";

export default function Dashboard() {
  const { data, loading, error } = useData<any>("/api/dashboard");

  if (loading) {
    return (
      <div className="flex h-[60vh] items-center justify-center">
        <Loader2 className="h-10 w-10 text-purple-600 animate-spin" />
      </div>
    );
  }

  if (error || !data) {
    return (
      <div className="p-8 text-center text-red-500 card-premium">
        Error loading dashboard: {error || "No data available"}
      </div>
    );
  }

  const { stats, recentSales, expiryAlerts, topSellingProducts } = data;

  const statCards = [
    {
      label: "Today's Sales",
      value: `PKR ${stats.todaySales.toLocaleString()}`,
      change: "+12.5%",
      trend: "up",
      icon: ShoppingCart,
      iconBg: "stat-icon-primary",
    },
    {
      label: "Total Revenue",
      value: `PKR ${stats.totalRevenue.toLocaleString()}`,
      change: "+20.1%",
      trend: "up",
      icon: DollarSign,
      iconBg: "stat-icon-success",
    },
    {
      label: "Low Stock Items",
      value: stats.lowStock.toString(),
      change: "Needs attention",
      trend: "warning",
      icon: Package,
      iconBg: "stat-icon-warning",
    },
    {
      label: "Expiring Soon",
      value: stats.expiringSoon.toString(),
      change: "Within 30 days",
      trend: "danger",
      icon: AlertTriangle,
      iconBg: "stat-icon-danger",
    },
  ];

  return (
    <div className="flex flex-col gap-8 animate-fade-in-up">
      {/* Page Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-black text-gray-900 uppercase tracking-tight">IR Operations</h1>
          <p className="text-gray-500 mt-1 font-medium">IR SOFTWARE Real-time Operational Pulse.</p>
        </div>
        <div className="flex items-center gap-3">
          <span className="text-sm text-gray-500 font-bold uppercase tracking-tighter">System Health: <span className="text-green-600">Optimal</span></span>
          <Link href="/reports" className="btn-primary flex items-center gap-2">
            <TrendingUp className="h-4 w-4" />
            IR Reports
          </Link>
        </div>
      </div>

      {/* Stats Grid */}
      <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-4">
        {statCards.map((stat, i) => (
          <div
            key={i}
            className="card-premium rounded-2xl p-6"
            style={{ animationDelay: `${i * 100}ms` }}
          >
            <div className="flex items-start justify-between">
              <div className={`stat-icon ${stat.iconBg}`}>
                <stat.icon className="h-6 w-6" />
              </div>
              {stat.trend === 'up' && (
                <span className="flex items-center gap-1 text-xs font-medium text-green-600 bg-green-50 px-2 py-1 rounded-full">
                  <ArrowUpRight className="h-3 w-3" />
                  {stat.change}
                </span>
              )}
              {stat.trend === 'warning' && (
                <span className="badge badge-warning">{stat.change}</span>
              )}
              {stat.trend === 'danger' && (
                <span className="badge badge-danger">{stat.change}</span>
              )}
            </div>
            <div className="mt-4">
              <p className="text-sm font-medium text-gray-500">{stat.label}</p>
              <p className="text-2xl font-bold text-gray-900 mt-1">{stat.value}</p>
            </div>
          </div>
        ))}
      </div>

      {/* Main Content Grid */}
      <div className="grid gap-6 lg:grid-cols-3">

        {/* Recent Sales */}
        <div className="lg:col-span-2 card-premium rounded-2xl p-6">
          <div className="flex items-center justify-between mb-6">
            <div>
              <h3 className="text-lg font-semibold text-gray-900">Recent Sales</h3>
              <p className="text-sm text-gray-500">Latest transactions today</p>
            </div>
            <Link href="/sales" className="text-sm font-medium text-purple-600 hover:text-purple-700">
              View All →
            </Link>
          </div>

          <div className="space-y-4">
            {recentSales.map((sale: any) => (
              <div key={sale.id} className="flex items-center gap-4 p-4 rounded-xl bg-gray-50/80 hover:bg-gray-100/80 transition-colors">
                <div className="w-12 h-12 rounded-xl bg-gradient-to-br from-purple-500 to-blue-500 flex items-center justify-center">
                  <Pill className="h-6 w-6 text-white" />
                </div>
                <div className="flex-1">
                  <p className="font-medium text-gray-900">{sale.medicine}</p>
                  <p className="text-sm text-gray-500">Qty: {sale.quantity} units</p>
                </div>
                <div className="text-right">
                  <p className="font-semibold text-gray-900">PKR {sale.amount.toLocaleString()}</p>
                  <p className="text-xs text-gray-400">{new Date(sale.time).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</p>
                </div>
              </div>
            ))}
            {recentSales.length === 0 && (
              <p className="py-8 text-center text-gray-400">No sales today yet.</p>
            )}
          </div>
        </div>

        {/* Expiry Alerts */}
        <div className="card-premium rounded-2xl p-6">
          <div className="flex items-center justify-between mb-6">
            <div>
              <h3 className="text-lg font-semibold text-gray-900">Expiry Alerts</h3>
              <p className="text-sm text-gray-500">Medicines expiring soon</p>
            </div>
            <span className="badge badge-danger">{expiryAlerts.length} Items</span>
          </div>

          <div className="space-y-4">
            {expiryAlerts.map((alert: any) => (
              <div
                key={alert.id}
                className={`alert-card ${alert.type === 'critical' ? 'alert-card-danger' :
                  alert.type === 'warning' ? 'alert-card-warning' : 'alert-card-success'
                  }`}
              >
                <div className="flex items-start gap-3">
                  <Clock className={`h-5 w-5 mt-0.5 ${alert.type === 'critical' ? 'text-red-500' :
                    alert.type === 'warning' ? 'text-orange-500' : 'text-green-500'
                    }`} />
                  <div className="flex-1">
                    <p className="font-medium text-gray-900">{alert.medicine}</p>
                    <p className="text-xs text-gray-500">{alert.batch}</p>
                    <div className="flex items-center justify-between mt-2">
                      <span className={`text-sm font-medium ${alert.type === 'critical' ? 'text-red-600' :
                        alert.type === 'warning' ? 'text-orange-600' : 'text-green-600'
                        }`}>
                        {alert.days} days left
                      </span>
                      <span className="text-xs text-gray-400">{alert.quantity} units</span>
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* Top Selling Products */}
      <div className="card-premium rounded-2xl p-6">
        <div className="flex items-center justify-between mb-6">
          <div>
            <h3 className="text-lg font-semibold text-gray-900">Top Selling Products</h3>
            <p className="text-sm text-gray-500">Best performers this month</p>
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full">
            <thead>
              <tr className="border-b border-gray-100">
                <th className="text-left py-4 px-4 text-sm font-medium text-gray-500">Product</th>
                <th className="text-left py-4 px-4 text-sm font-medium text-gray-500">Units Sold</th>
                <th className="text-left py-4 px-4 text-sm font-medium text-gray-500">Revenue</th>
                <th className="text-left py-4 px-4 text-sm font-medium text-gray-500">Current Stock</th>
                <th className="text-left py-4 px-4 text-sm font-medium text-gray-500">Status</th>
              </tr>
            </thead>
            <tbody>
              {topSellingProducts.map((product: any, i: number) => (
                <tr key={i} className="border-b border-gray-50 hover:bg-gray-50/50 transition-colors">
                  <td className="py-4 px-4">
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 rounded-lg bg-gradient-to-br from-purple-100 to-blue-100 flex items-center justify-center">
                        <Pill className="h-5 w-5 text-purple-600" />
                      </div>
                      <span className="font-medium text-gray-900">{product.name}</span>
                    </div>
                  </td>
                  <td className="py-4 px-4 text-gray-600">{product.sold}</td>
                  <td className="py-4 px-4 font-medium text-gray-900">PKR {product.revenue.toLocaleString()}</td>
                  <td className="py-4 px-4 text-gray-600">{product.stock}</td>
                  <td className="py-4 px-4">
                    <span className={`badge ${product.stock > 100 ? 'badge-success' : product.stock > 30 ? 'badge-warning' : 'badge-danger'}`}>
                      {product.stock > 100 ? 'In Stock' : product.stock > 30 ? 'Low Stock' : 'Critical'}
                    </span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}
